    for file in "${files[@]:0:20}"; do
        [[ -f "$file" ]] || continue
        gawk '
            {
                while (match($0, /\{\{[[:space:]]*[A-Za-z_][A-Za-z0-9_.-]*[[:space:]]*\}\}/)) {
                    name = substr($0, RSTART + 2, RLENGTH - 4)
                    gsub(/^[[:space:]]+|[[:space:]]+$/, "", name)
                    print name
                    $0 = substr($0, RSTART + RLENGTH)
                }
            }
            /^[[:space:]]*(variable|secret)[[:space:]]*:/ {
                name = $0
                sub(/^[^:]*:/, "", name)
                sub(/=.*/, "", name)
                gsub(/^[[:space:]]+|[[:space:]]+$/, "", name)
                if (name != "") print name
            }
        ' "$file"
    done
    if [[ -n "$argc_variables_file" && -f "$argc_variables_file" ]]; then
        gawk '!/^[[:space:]]*[#!]/ && /=/ {
            name = $0
            sub(/=.*/, "", name)
            gsub(/^[[:space:]]+|[[:space:]]+$/, "", name)
            if (name != "") print name
        }' "$argc_variables_file"
    fi
